    def _get_inspector(
        self, database: Optional[str] = None
    ) -> Iterator[Optional[Inspector]]:
        """Yield an inspector, switching databases first when required.

        For dialects that require a USE DATABASE command (Snowflake), a new
        connection is opened, the database is switched, and an inspector bound
        to that connection is yielded. For all other dialects, the cached
        ``self.inspector`` is yielded without opening a connection.
        """
