        else:
            yield self.inspector

    @staticmethod
    def _extract_index_columns(indexes: list[Any]) -> list[str]:
        """Extract and deduplicate column names from a list of index dicts.

        Skips ``None`` values within ``column_names`` lists and index entries
        that lack a ``column_names`` key. Insertion order is preserved while
        deduplicating.
        """
        seen: set[str] = set()
        result: list[str] = []
        for index in indexes:
            if "column_names" not in index:
                continue
            for col in index["column_names"] or []:
                if col is None or col in seen:
                    continue
                seen.add(col)
                result.append(col)
        return result

